<?php use App\Services\Publisher; ?>
<div class="page-heading"><div><div class="eyebrow">WORKSPACE RECORDS</div><h1>Publishing History</h1><p>Review local drafts, WordPress results, and publishing activity.</p></div></div><div class="alert phase-alert">Phase 2: local saves stay in Hub. WordPress Draft and Publish run only when an authorized user chooses them.</div>
<div class="surface table-responsive"><table class="table"><thead><tr><th>Announcement</th><th>Module</th><th>Created by</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $a): $link=Publisher::remoteLink($a); ?><tr><td><strong><?= e($a['title']) ?></strong><small class="d-block text-secondary mt-1"><?= e($a['created_at']) ?> UTC</small><?php if($a['body']): ?><details class="mt-2"><summary>Read announcement</summary><p class="preserve-lines mt-3"><?= e($a['body']) ?></p></details><?php endif; ?><?php if($a['image_path']): ?><details class="mt-2"><summary>View poster</summary><img class="history-poster" src="<?= e(url('/image?id='.$a['id'])) ?>" alt="<?= e($a['title']) ?>" loading="lazy"></details><?php endif; ?></td><td><?= $a['type']==='partial'?'Partial update':'Scheduled interruption' ?></td><td><?= e($a['author']) ?></td><td><span class="status-badge"><?= e(Publisher::status($a)) ?></span><?php if($a['wordpress_post_id']): ?><small class="d-block mt-2">WordPress #<?= e($a['wordpress_post_id']) ?></small><?php endif; ?><?php if($a['wordpress_post_id'] && (int)$a['synced_revision']!==(int)$a['revision']): ?><small class="d-block mt-2">Local changes pending</small><?php endif; ?><?php if($a['publish_error']): ?><p class="publish-error mt-2"><?= e($a['publish_error']) ?></p><?php endif; ?></td><td><a class="btn btn-sm btn-outline-secondary mb-2" href="<?= e(url('/announcement?id='.$a['id'])) ?>"><?= $a['status']==='failed'?'Review / retry':'Review / publish' ?></a><?php if($link && $a['wordpress_status']==='publish'): ?><a class="text-link d-block" href="<?= e($link) ?>" target="_blank" rel="noopener noreferrer">View on WordPress ↗</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state"><h3>No announcements yet</h3><p>Save an announcement draft to start your history.</p></div></td></tr><?php endif; ?></tbody></table></div>
<h2 class="mt-4 mb-3">Publishing events</h2><div class="surface table-responsive"><table class="table"><thead><tr><th>Announcement</th><th>Status</th><th>Publisher</th><th>Result</th><th>Time (UTC)</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= e($h['title']) ?></td><td><?= e($h['status']) ?></td><td><?= e($h['author']) ?></td><td><?= e($h['message']) ?><?php if($h['wordpress_post_id']): ?> · #<?= e($h['wordpress_post_id']) ?><?php endif; ?></td><td><?= e($h['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="5" class="text-secondary p-4">No publishing events recorded.</td></tr><?php endif; ?></tbody></table></div>
